            [Q('en_lac', 'By numbers, lacI has 1100 bps, lacZ has 3000 bps, lacY has 800 bps, lacA has 800 bps, with 3 bps corresponding to 1 amino acid.'), Q('es_lac', 'Presenta tres genes estructurales adyacentes, un promotor, un regulador y un operador.')],
